item.command:
/bin/bash -lc "sed -n '1,240p' /codex_home/skills/galaxy-tool-submission/SKILL.md && find inputs -maxdepth 2 -type f | wc -l && python - <<'PY'
import openpyxl, os, glob, json
for f in ['inputs/230214_Schenz_et_al_2022_CHIP_Genes.xlsx','inputs/230215_Trio_Status.xlsx'] + glob.glob('inputs/CHIP_DP10_GQ20_PASS/*.xlsx')[:2]:
    w=openpyxl.load_workbook(f, read_only=True, data_only=True)
    print('\\nFILE',os.path.basename(f), 'sheets',w.sheetnames)
    for s in w.worksheets:
      print('SHEET',s.title,'dim',s.max_row,s.max_column)
      for row in s.iter_rows(min_row=1,max_row=min(5,s.max_row),values_only=True): print(row)
PY"

/bin/bash -lc "sed -n '1,240p' /codex_home/skills/galaxy-tool-submission/SKILL.md && find inputs -maxdepth 2 -type f | wc -l && python - <<'PY'
import openpyxl, os, glob, json
for f in ['inputs/230214_Schenz_et_al_2022_CHIP_Genes.xlsx','inputs/230215_Trio_Status.xlsx'] + glob.glob('inputs/CHIP_DP10_GQ20_PASS/*.xlsx')[:2]:
    w=openpyxl.load_workbook(f, read_only=True, data_only=True)
    print('\\nFILE',os.path.basename(f), 'sheets',w.sheetnames)
    for s in w.worksheets:
      print('SHEET',s.title,'dim',s.max_row,s.max_column)
      for row in s.iter_rows(min_row=1,max_row=min(5,s.max_row),values_only=True): print(row)
PY"

